def transform(grid):
    if not grid:
        return []
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Extend a periodic row pattern into the trailing background, with
        # the novel color 1 marking each continuation cell.
        marks = [c for c, v in enumerate(row) if v != bg]
        if len(marks) < 4 or marks[-1] == len(row) - 1:
            continue
        # Find the shortest period supported by the full observed prefix.
        seq = row[:marks[-1] + 1]
        period = next((p for p in range(1, len(seq)//2 + 1)
                       if all(seq[i] == seq[i-p] for i in range(p, len(seq)))), None)
        if period is None:
            continue
        # Only continue when the sequence ends in a repeated non-background
        # pattern and the observed tail includes more than one cycle.
        for c in range(marks[-1] + 1, len(row)):
            out[r][c] = 1
    return out

